from devpilot.core.message import Message
from devpilot.core.model import Model


VALID_CATEGORIES = {
    "project_fact",
    "decision",
    "constraint",
    "preference",
    "lesson",
}


@dataclass
class ExtractedMemory:
    content: str
    category: str
    tags: list[str]


class MemoryExtractor:

    def __init__(self,model: Model):
        self.model = model

    def extract(
        self,
        user_input: str,
        assistant_output: str,
    ) -> list[ExtractedMemory]:

        prompt = f"""
Analyze this completed interaction.

User:
{user_input}

Assistant:
{assistant_output}

Extract only information that is likely
to remain useful in future sessions.

Good memory examples:
- stable project facts
- architecture decisions
- explicit constraints
- important lessons
- durable user/project preferences

Do NOT store:
- greetings
- temporary progress
- obvious transient tool output
- information useful only in this turn

Return ONLY a JSON array.

Each item must be:

{{
  "content": "...",
  "category": "project_fact|decision|constraint|preference|lesson",
  "tags": ["...", "..."]
}}

If nothing deserves long-term storage,
return [].
""".strip()

        response = self.model.complete(
            messages=[
                Message(
                    role="user",
                    content=prompt,
                )
            ],
            tools=None,
            system=(
                "You extract durable "
                "project memory. "
                "Return valid JSON only."
            ),
        )
        raw = response.content.strip()
        raw = self._strip_code_fence(raw)
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            return []
        if not isinstance(data, list):
            return []
        results = []
        for item in data:
            if not isinstance(item,dict):
                continue
            content = item.get("content")
            category = item.get("category")
            tags = item.get("tags",[])
            if not isinstance(content,str):
                continue
            if (category not in VALID_CATEGORIES):
                continue
            if not isinstance(tags,list):
                tags = []
            tags = [
                tag
                for tag in tags
                if isinstance(tag,str)
            ]
            results.append(
                ExtractedMemory(
                    content=content,
                    category=category,
                    tags=tags,
                )
            )

        return results

    @staticmethod
    def _strip_code_fence(
        text: str,
    ) -> str:

        match = re.fullmatch(
            r"```(?:json)?\s*(.*?)\s*```",
            text,
            flags=re.DOTALL,
        )

        if match:
            return match.group(1)

        return text

import re

from devpilot.memory.store import (
    MemoryItem,
    MemoryStore,
)


def normalize_memory(text: str,) -> str:

    return re.sub(
        r"\s+",
        " ",
        text.strip().lower(),
    )


class MemoryConsolidator:

    def __init__(self,store: MemoryStore):
        self.store = store

    def save(
        self,
        content: str,
        category: str,
        tags: list[str] | None = None,
        source: str = "agent",
    ) -> MemoryItem:

        normalized = normalize_memory(content)
        new_tags = set(tags or [])
        for item in self.store.all():
            if (normalize_memory(item.content)!= normalized):
                continue
            merged_tags = (set(item.tags) | new_tags)
            item.tags = sorted(merged_tags)
            self.store.update(item)
            return item

        return self.store.add(
            content=content,
            category=category,
            tags=sorted(new_tags),
            source=source,
        )

from dataclasses import asdict, dataclass
from datetime import datetime, timezone
import json
from pathlib import Path
from uuid import uuid4


@dataclass
class MemoryItem:
    id: str
    content: str
    category: str
    tags: list[str]
    source: str
    created_at: str
    updated_at: str


class MemoryStore:

    def __init__(self,path: Path,):
        self.path = path.resolve()
        self.path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        if not self.path.exists():
            self._save([])

    def all(self) -> list[MemoryItem]:
        raw_items = self._load()
        return [
            MemoryItem(**item)
            for item in raw_items
        ]

    def get(self,memory_id: str) -> MemoryItem | None:
        for item in self.all():
            if item.id == memory_id:
                return item
        return None

    def add(
        self,
        content: str,
        category: str,
        tags: list[str] | None = None,
        source: str = "agent",
    ) -> MemoryItem:
        now = datetime.now(timezone.utc).isoformat()
        item = MemoryItem(
            id=(
                "mem_"
                + uuid4().hex[:12]
            ),
            content=content,
            category=category,
            tags=tags or [],
            source=source,
            created_at=now,
            updated_at=now,
        )
        items = self.all()
        items.append(item)
        self._save_items(items)
        return item

    def update(self,item: MemoryItem) -> None:

        items = self.all()
        item.updated_at = datetime.now(timezone.utc).isoformat()
        updated = []
        found = False
        for existing in items:
            if existing.id == item.id:
                updated.append(item)
                found = True
            else:
                updated.append(existing)
        if not found:
            raise ValueError(
                f"Unknown memory: {item.id}"
            )
        self._save_items(updated)

    def _load(self) -> list[dict]:
        try:
            text = self.path.read_text(encoding="utf-8")
            data = json.loads(text)

        except (
            json.JSONDecodeError,
            OSError,
        ) as error:
            raise RuntimeError(
                f"Failed to load memory "
                f"store: {error}"
            ) from error
        if not isinstance(data, list):
            raise RuntimeError(
                "Memory store must "
                "contain a JSON list"
            )
        return data

    def _save_items(self,items: list[MemoryItem]) -> None:
        self._save(
            [
                asdict(item)
                for item in items
            ]
        )

    def _save(self,data: list[dict]) -> None:
        temp = self.path.with_suffix(".tmp")
        temp.write_text(
            json.dumps(
                data,
                ensure_ascii=False,
                indent=2,
            ),
            encoding="utf-8",
        )
        temp.replace(self.path)

