class Agent:

    def __init__(
        self,
        model: Model,
        tools: ToolRegistry,
        hooks: HookManager,
        context: ContextManager,
        memory: MemoryManager,
        tasks: TaskScheduler,
        max_steps: int = 200,
    ):
        self.model = model
        self.tools = tools
        self.hooks = hooks
        self.context = context
        self.memory = memory
        self.tasks = tasks

        self.max_steps = max_steps

        self.dispatcher = (
            ToolDispatcher(
                registry=tools,
                hooks=hooks,
            )
        )

        self.messages: list[
            Message
        ] = []

    def run(self,user_input: str) -> str:
        self.messages.append(
            Message(
                role="user",
                content=user_input,
            )
        )
        for _ in range(
            self.max_steps
        ):

            # =========================
            # Active Context
            # =========================
            prepared = (
                self.context.prepare(
                    self.messages
                )
            )

            self.messages[:] = (
                prepared
            )

            # =========================
            # Persistent Memory
            # =========================

            memory_context = (
                self.memory.recall(
                    user_input
                )
            )

            # =========================
            # Persistent Task Graph
            # =========================

            task_context = (
                self.tasks.render()
            )

            # =========================
            # Build System Prompt
            # =========================

            system = (
                self.context
                .build_system_prompt(
                    extra_sections=[
                        (
                            "## Relevant "
                            "Persistent Memory\n"
                            f"{memory_context}"
                        ),

                        (
                            "## Persistent "
                            "Task Graph\n"
                            f"{task_context}"
                        ),
                    ]
                )
            )

            # =========================
            # Model
            # =========================

            response = (
                self.model.complete(
                    messages=(
                        self.messages
                    ),
                    tools=(
                        self.tools.schemas()
                    ),
                    system=system,
                )
            )

            # =========================
            # Assistant Message
            # =========================

            self.messages.append(
                Message(
                    role="assistant",
                    content=response.content,
                    tool_calls=(
                        response.tool_calls
                    ),
                )
            )

            # =========================
            # Stop
            # =========================

            if not response.tool_calls:

                self.memory.capture_turn(
                    user_input=(
                        user_input
                    ),
                    assistant_output=(
                        response.content
                    ),
                )

                return response.content

            # =========================
            # Tool Calls
            # =========================

            for tool_call in (
                response.tool_calls
            ):

                result = (
                    self.dispatcher
                    .execute(
                        tool_call
                    )
                )

                self.messages.append(
                    Message(
                        role="tool",
                        content=result,
                        tool_call_id=(
                            tool_call.id
                        ),
                    )
                )

        raise RuntimeError(
            "Agent exceeded "
            f"{self.max_steps} steps"
        )

from dataclasses import dataclass
from typing import Any

from devpilot.tools.base import Tool


VALID_STATUSES = {
    "pending",
    "in_progress",
    "completed",
}


@dataclass
class TodoItem:
    content: str
    status: str


class TodoManager:

    def __init__(self):
        self.items: list[TodoItem] = []

    def replace(
        self,
        raw_items: list[dict[str, Any]],
    ) -> str:

        new_items: list[TodoItem] = []

        for raw in raw_items:

            content = raw.get("content")
            status = raw.get("status")

            if not isinstance(content, str):
                return (
                    "Error: todo content "
                    "must be a string"
                )

            if status not in VALID_STATUSES:
                return (
                    "Error: todo status must be "
                    "pending, in_progress, "
                    "or completed"
                )

            new_items.append(
                TodoItem(
                    content=content,
                    status=status,
                )
            )

        self.items = new_items

        return self.render()

    def render(self) -> str:

        if not self.items:
            return "(no todos)"

        lines = []

        for index, item in enumerate(
            self.items,
            start=1,
        ):

            lines.append(
                f"{index}. "
                f"[{item.status}] "
                f"{item.content}"
            )

        return "\n".join(lines)


def create_todo_tool(
    manager: TodoManager,
) -> Tool:

    def handler(
        arguments: dict[str, Any],
    ) -> str:

        items = arguments.get("items")

        if not isinstance(items, list):
            return (
                "Error: items must "
                "be a list"
            )

        return manager.replace(items)

    return Tool(
        name="todo_write",

        description=(
            "Replace the current task plan. "
            "Use this for multi-step work "
            "to track pending, in-progress, "
            "and completed steps."
        ),

        parameters={
            "type": "object",

            "properties": {
                "items": {
                    "type": "array",

                    "items": {
                        "type": "object",

                        "properties": {

                            "content": {
                                "type": "string"
                            },

                            "status": {
                                "type": "string",
                                "enum": [
                                    "pending",
                                    "in_progress",
                                    "completed",
                                ],
                            },
                        },

                        "required": [
                            "content",
                            "status",
                        ],

                        "additionalProperties": False,
                    },
                }
            },

            "required": [
                "items"
            ],

            "additionalProperties": False,
